Here is the commit message:
HADOOP-13183. S3A proxy tests fail after httpclient/httpcore
 upgrade. Contributed by Steve Loughran.

Here is the root cause:
The bug was caused by changes in the exception messages thrown by the `AmazonClientException` after an upgrade of the `httpclient/httpcore` libraries. The tests were originally designed to check for specific messages in the exception, which led to failures when the expected messages changed. The modifications made in the patch removed these specific checks, allowing the tests to pass as they now only expect the occurrence of the exception without validating the message content.

Here is the patch:

   @Test
   public void testProxyConnection() throws Exception {
     conf = new Configuration();
     conf.setInt(Constants.MAX_ERROR_RETRIES, 2);
     conf.set(Constants.PROXY_HOST, "127.0.0.1");
     conf.setInt(Constants.PROXY_PORT, 1);
     String proxy =
         conf.get(Constants.PROXY_HOST) + ":" + conf.get(Constants.PROXY_PORT);
     try {
       fs = S3ATestUtils.createTestFileSystem(conf);
       fail("Expected a connection error for proxy server at " + proxy);
     } catch (AmazonClientException e) {
-      if (!e.getMessage().contains(proxy + " refused")) {
-        throw e;
-      }
+      // expected
     }
   }


   @Test
   public void testAutomaticProxyPortSelection() throws Exception {
     conf = new Configuration();
     conf.unset(Constants.PROXY_PORT);
     conf.setInt(Constants.MAX_ERROR_RETRIES, 2);
     conf.set(Constants.PROXY_HOST, "127.0.0.1");
     conf.set(Constants.SECURE_CONNECTIONS, "true");
     try {
       fs = S3ATestUtils.createTestFileSystem(conf);
       fail("Expected a connection error for proxy server");
     } catch (AmazonClientException e) {
-      if (!e.getMessage().contains("443")) {
-        throw e;
-      }
+      // expected
     }
     conf.set(Constants.SECURE_CONNECTIONS, "false");
     try {
       fs = S3ATestUtils.createTestFileSystem(conf);
       fail("Expected a connection error for proxy server");
     } catch (AmazonClientException e) {
-      if (!e.getMessage().contains("80")) {
-        throw e;
-      }
+      // expected
     }
   }



